fac=pd.DataFrame(index=prices.index,columns=assets,dtype=float)
for a in assets:
    x=r[a]; beta=x.rolling(60,min_periods=40).cov(zd)/zd.rolling(60,min_periods=40).var().replace(0,np.nan)
    resid=x-beta*zd
    fac[a]=resid.rolling(20,min_periods=15).sum()
